"use client";

import { forwardRef, type CSSProperties, type HTMLAttributes } from "react";
import { comicTextDefaults, type ComicTextSpecProps } from "../generated/comic-text.types";
import { cx } from "../utils/cx";

export interface ComicTextProps
  extends ComicTextSpecProps,
    Omit<HTMLAttributes<HTMLSpanElement>, keyof ComicTextSpecProps | "className" | "children"> {
  className?: string;
}

/**
 * Bold, outlined text with a hard offset shadow. Pure CSS and real text. The optional pop-in plays once
 * when the element first appears; reduced motion and isPaused skip it.
 */
export const ComicText = forwardRef<HTMLSpanElement, ComicTextProps>(function ComicText(
  { children, popIn = comicTextDefaults.popIn, fill = comicTextDefaults.fill, outline = comicTextDefaults.outline, isPaused = comicTextDefaults.isPaused, className, style, ...rest },
  ref,
) {
  return (
    <span
      {...rest}
      ref={ref}
      data-rdm-paused={isPaused || undefined}
      data-pop={popIn || undefined}
      className={cx("rdm-comic", className)}
      style={{ "--rdm-fill": fill, "--rdm-line": outline, ...style } as CSSProperties}
    >
      {children}
    </span>
  );
});

// Generated by rdloom codegen from specs/comic-text.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

/** Bold, outlined, comic-style text with a hard offset shadow and an optional pop-in when it first appears. */
export interface ComicTextSpecProps {
  /**
   * The text.
   */
  children: string;
  /**
   * Plays one short pop when the text first appears.
   * @default false
   */
  popIn?: boolean;
  /**
   * Letter colour, any CSS colour.
   * @default "var(--rd-color-surface-default)"
   */
  fill?: string;
  /**
   * Outline and shadow colour, any CSS colour.
   * @default "var(--rd-color-text-default)"
   */
  outline?: string;
  /**
   * Skips the pop-in and shows the text plainly.
   * @default false
   */
  isPaused?: boolean;
}

export const comicTextDefaults = {
  popIn: false,
  fill: "var(--rd-color-surface-default)",
  outline: "var(--rd-color-text-default)",
  isPaused: false,
} as const;

export const comicTextMeta = {
  "name": "ComicText",
  "version": "0.1.0",
  "status": "experimental",
  "role": "text"
} as const;
